create or replace function public.v21_verify_transfer_execution(p_transfer_id uuid) returns jsonb language plpgsql security definer set search_path=public as $v21$ declare t public.stock_transfers; l record; stock numeric; floor numeric; result jsonb:='[]'::jsonb; begin select * into t from public.stock_transfers where id=p_transfer_id; if t.id is null then raise exception 'Stock transfer not found'; end if; if not is_member(t.business_id) then raise exception 'Not authorized for this business'; end if; for l in select * from public.stock_transfer_lines where stock_transfer_id=t.id order by id loop select coalesce(sum(quantity),0) into stock from public.v19_location_stock where business_id=t.business_id and location_id=t.source_location_id and ingredient_id=l.ingredient_id and unit=l.unit; select coalesce(reorder_point,0)+coalesce(safety_stock,0) into floor from public.view_v20_location_reorder where business_id=t.business_id and location_id=t.source_location_id and ingredient_id=l.ingredient_id and unit=l.unit; result:=result||jsonb_build_array(jsonb_build_object('ingredient_id',l.ingredient_id,'quantity',l.quantity,'unit',l.unit,'current_stock',stock,'protected_floor',floor,'dispatch_allowed',stock-l.quantity>=floor)); end loop; return jsonb_build_object('transfer_id',t.id,'dispatch_allowed',not exists(select 1 from jsonb_array_elements(result) x where coalesce((x->>'dispatch_allowed')::boolean,false)=false),'lines',result); end $v21$; grant execute on function public.v21_verify_transfer_execution(uuid) to authenticated; create or replace function public.v21_audit_allocation_insert() returns trigger language plpgsql security definer set search_path=public as $v21$ begin insert into public.audit_logs(business_id,action,entity_type,entity_id,metadata,created_by,created_at) values(new.business_id,'SupplyAllocationCreated',tg_table_name,new.id,jsonb_build_object('location_id',new.location_id,'quantity',new.allocated_quantity,'unit',new.unit),auth.uid(),now()); return new; end $v21$; drop trigger if exists v21_plan_allocation_audit on public.v21_purchase_plan_allocations; create trigger v21_plan_allocation_audit after insert on public.v21_purchase_plan_allocations for each row execute function public.v21_audit_allocation_insert(); drop trigger if exists v21_po_allocation_audit on public.v21_purchase_order_allocations; create trigger v21_po_allocation_audit after insert on public.v21_purchase_order_allocations for each row execute function public.v21_audit_allocation_insert();